/* 自动备份插件：监听 save 事件，节流后把全书写入 data/backups/ 滚动备份。
 * 文件操作统一走 ctx.electronAPI.pluginFs（主进程沙箱，限定在 data 目录内）。
 * 设置区：可调保留份数（默认 20）与最小间隔（默认 5 分钟），列出全部备份可逐份恢复。 */
(function () {
  'use strict';
  const DEF_KEEP = 20;
  const DEF_INTERVAL = 5 * 60 * 1000;

  window.MoyePlugins.register({
    id: 'auto-backup',
    name: '自动备份',
    activate(ctx) {
      this._ctx = ctx;
      this._last = 0;
      this._onSave = () => this.maybeBackup();
      ctx.on('save', this._onSave);

      const keep = ctx.getSetting('autoBackupKeep', DEF_KEEP);
      const interval = ctx.getSetting('autoBackupInterval', DEF_INTERVAL);

      ctx.ui.addSettingsSection({
        title: '自动备份（全书快照）',
        render: (c) => {
          const tip = document.createElement('p');
          tip.className = 'muted';
          tip.style.cssText = 'font-size:12px;line-height:1.6;margin:0 0 8px';
          tip.textContent = '保存后自动滚动备份到 data/backups/。';
          c.appendChild(tip);

          const optRow = document.createElement('div');
          optRow.className = 'tool-row';
          optRow.style.marginBottom = '8px';
          optRow.innerHTML =
            '<label class="set-check">保留 <input type="number" id="abKeep" min="1" max="200" value="' + keep + '" style="width:56px"> 份</label>' +
            '<label class="set-check">最小间隔 <input type="number" id="abInt" min="1" max="120" value="' + Math.round(interval / 60000) + '" style="width:48px"> 分</label>';
          c.appendChild(optRow);
          const keepInput = optRow.querySelector('#abKeep');
          const intInput = optRow.querySelector('#abInt');
          keepInput.addEventListener('change', () => ctx.setSetting('autoBackupKeep', Math.max(1, parseInt(keepInput.value) || DEF_KEEP)));
          intInput.addEventListener('change', () => ctx.setSetting('autoBackupInterval', Math.max(1, parseInt(intInput.value) || 5) * 60000));

          const row = document.createElement('div');
          row.className = 'tool-row';
          row.style.marginBottom = '10px';
          const backupNow = document.createElement('button');
          backupNow.className = 'mini-btn primary';
          backupNow.textContent = '立即备份';
          backupNow.addEventListener('click', () => this.backupNow(true));
          const restore = document.createElement('button');
          restore.className = 'mini-btn';
          restore.textContent = '恢复最近一份';
          restore.addEventListener('click', () => this.restoreLatest());
          row.appendChild(backupNow);
          row.appendChild(restore);
          c.appendChild(row);

          const listTitle = document.createElement('div');
          listTitle.className = 'muted';
          listTitle.style.cssText = 'font-size:12px;margin-bottom:4px';
          listTitle.textContent = '可恢复备份（点击恢复该份）';
          c.appendChild(listTitle);

          const list = document.createElement('div');
          list.id = 'abList';
          list.style.cssText = 'max-height:180px;overflow:auto';
          c.appendChild(list);
          this._listEl = list;
          this.renderList();
        }
      });
    },

    async renderList() {
      const ctx = this._ctx, list = this._listEl;
      if (!list) return;
      list.innerHTML = '<div class="muted" style="font-size:12px">读取中…</div>';
      try {
        const r = await ctx.electronAPI.pluginFs({ op: 'list', rel: 'backups' });
        if (!r || !r.ok) { list.innerHTML = '<div class="muted" style="font-size:12px">读取失败</div>'; return; }
        const files = r.items.filter((n) => /^novels-.*\.json$/.test(n)).sort().reverse();
        if (!files.length) { list.innerHTML = '<div class="muted" style="font-size:12px">还没有备份</div>'; return; }
        list.innerHTML = '';
        files.slice(0, 50).forEach((f) => {
          const item = document.createElement('div');
          item.className = 'tool-row';
          item.style.cssText = 'justify-content:space-between;padding:4px 0;border-bottom:1px solid var(--line)';
          const label = document.createElement('span');
          label.style.cssText = 'font-size:12px';
          label.textContent = f.replace(/^novels-/, '').replace(/\.json$/, '').replace(/-/g, ':');
          const btn = document.createElement('button');
          btn.className = 'mini-btn';
          btn.textContent = '恢复';
          btn.addEventListener('click', () => this.restoreFile(f));
          item.appendChild(label);
          item.appendChild(btn);
          list.appendChild(item);
        });
      } catch (e) {
        list.innerHTML = '<div class="muted" style="font-size:12px">读取失败</div>';
      }
    },

    getKeep() { return Math.max(1, this._ctx.getSetting('autoBackupKeep', DEF_KEEP)); },
    getInterval() { return Math.max(1, this._ctx.getSetting('autoBackupInterval', DEF_INTERVAL)); },

    maybeBackup() {
      const now = Date.now();
      if (now - this._last < this.getInterval()) return;
      this.backupNow(false);
    },

    async backupNow(manual) {
      const ctx = this._ctx;
      try {
        const db = ctx.getDb();
        const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
        const rel = 'backups/novels-' + stamp + '.json';
        const r = await ctx.electronAPI.pluginFs({ op: 'write', rel, content: JSON.stringify(db, null, 2) });
        if (!r || !r.ok) { if (manual) ctx.toast('备份失败：' + (r && r.error)); return; }
        this._last = Date.now();
        await this.prune();
        if (manual) { ctx.toast('已备份全书'); this.renderList(); }
      } catch (e) {
        console.error('[自动备份]', e);
        if (manual) ctx.toast('备份失败');
      }
    },

    async prune() {
      const ctx = this._ctx;
      try {
        const r = await ctx.electronAPI.pluginFs({ op: 'list', rel: 'backups' });
        if (!r || !r.ok) return;
        const files = r.items.filter((n) => /^novels-.*\.json$/.test(n)).sort();
        const keep = this.getKeep();
        while (files.length > keep) {
          const old = files.shift();
          await ctx.electronAPI.pluginFs({ op: 'delete', rel: 'backups/' + old });
        }
      } catch (e) { console.error('[自动备份] 清理', e); }
    },

    async restoreFile(f) {
      const ctx = this._ctx;
      try {
        const rd = await ctx.electronAPI.pluginFs({ op: 'read', rel: 'backups/' + f });
        if (!rd || !rd.ok) { ctx.toast('读取失败'); return; }
        ctx.replaceDb(JSON.parse(rd.content));
        ctx.toast('已恢复：' + f);
        this.renderList();
      } catch (e) {
        console.error('[自动备份] 恢复', e);
        ctx.toast('恢复失败');
      }
    },

    async restoreLatest() {
      const ctx = this._ctx;
      try {
        const r = await ctx.electronAPI.pluginFs({ op: 'list', rel: 'backups' });
        if (!r || !r.ok) { ctx.toast('读取备份失败'); return; }
        const files = r.items.filter((n) => /^novels-.*\.json$/.test(n)).sort();
        if (!files.length) { ctx.toast('还没有备份'); return; }
        await this.restoreFile(files[files.length - 1]);
      } catch (e) {
        console.error('[自动备份] 恢复', e);
        ctx.toast('恢复失败');
      }
    },

    deactivate() {
      if (this._ctx && this._onSave) this._ctx.off('save', this._onSave);
    }
  });
})();

/* 全文搜索插件：在本书全部章节里搜关键词，点结果跳转。
 * 支持「区分大小写」「正则」两个开关。仅用宿主暴露的 ctx API，不碰任何内部变量。 */
(function () {
  'use strict';
  window.MoyePlugins.register({
    id: 'fulltext-search',
    name: '全文搜索',
    activate(ctx) {
      this._ctx = ctx;
      this.caseSensitive = false;
      this.useRegex = false;
      ctx.ui.addToolbarButton({ label: '搜索', title: '跨章节搜索全书', onClick: () => this.open() });
    },
    open() {
      const ctx = this._ctx;
      ctx.ui.openModal({
        title: '全文搜索',
        render: (body) => {
          const input = document.createElement('input');
          input.className = 'fts-input';
          input.placeholder = '输入关键词，即时搜索（全书所有章节）';
          const opts = document.createElement('div');
          opts.className = 'tool-row';
          opts.style.cssText = 'margin-bottom:8px';
          opts.innerHTML =
            '<label class="set-check"><input type="checkbox" id="ftsCase"> 区分大小写</label>' +
            '<label class="set-check"><input type="checkbox" id="ftsRe"> 正则</label>';
          const caseCb = opts.querySelector('#ftsCase');
          const reCb = opts.querySelector('#ftsRe');
          caseCb.checked = this.caseSensitive;
          reCb.checked = this.useRegex;
          caseCb.addEventListener('change', () => { this.caseSensitive = caseCb.checked; run(); });
          reCb.addEventListener('change', () => { this.useRegex = reCb.checked; run(); });

          const count = document.createElement('div');
          count.className = 'fts-count';
          const list = document.createElement('div');
          body.appendChild(input);
          body.appendChild(opts);
          body.appendChild(count);
          body.appendChild(list);

          let timer = null;
          const run = () => {
            const q = input.value.trim();
            if (!q) { count.textContent = ''; list.innerHTML = ''; return; }
            const book = ctx.getActiveBook();
            if (!book) { count.textContent = '未打开作品'; return; }

            let re = null;
            if (this.useRegex) {
              try { re = new RegExp(q, this.caseSensitive ? 'g' : 'gi'); }
              catch (e) { count.textContent = '正则无效：' + e.message; list.innerHTML = ''; return; }
            }
            const ql = this.caseSensitive ? q : q.toLowerCase();

            const hits = [];
            book.volumes.forEach((v) => {
              if (hits.length >= 200) return;
              v.chapters.forEach((c) => {
                if (hits.length >= 200) return;
                const text = ctx.htmlToText(c.html || '');
                if (!text) return;
                if (re) {
                  re.lastIndex = 0; let m;
                  while ((m = re.exec(text)) !== null) {
                    if (m.index === re.lastIndex) re.lastIndex++;
                    if (hits.length >= 200) break;
                    const start = Math.max(0, m.index - 14);
                    const end = Math.min(text.length, m.index + m[0].length + 14);
                    let sn = text.slice(start, end);
                    if (start > 0) sn = '…' + sn;
                    if (end < text.length) sn = sn + '…';
                    hits.push({ chId: c.id, chTitle: c.title || '未命名', vol: v.name, text: sn, hit: m[0] });
                  }
                } else {
                  const tl = this.caseSensitive ? text : text.toLowerCase();
                  let idx = tl.indexOf(ql);
                  while (idx !== -1 && hits.length < 200) {
                    const start = Math.max(0, idx - 14);
                    const end = Math.min(text.length, idx + ql.length + 14);
                    let sn = text.slice(start, end);
                    if (start > 0) sn = '…' + sn;
                    if (end < text.length) sn = sn + '…';
                    hits.push({ chId: c.id, chTitle: c.title || '未命名', vol: v.name, text: sn, hit: ql });
                    idx = tl.indexOf(ql, idx + ql.length);
                  }
                }
              });
            });

            count.textContent = '命中 ' + hits.length + ' 处' + (hits.length >= 200 ? '（仅显示前 200）' : '');
            list.innerHTML = '';
            if (!hits.length) { list.innerHTML = '<div class="empty-tip">没有匹配结果</div>'; return; }
            const escHit = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            hits.forEach((h) => {
              const item = document.createElement('div');
              item.className = 'fts-item';
              const needle = h.hit || q;
              const hl = h.text.replace(new RegExp(escHit(needle), this.caseSensitive ? 'g' : 'gi'), (m) => '<mark>' + m + '</mark>');
              item.innerHTML = '<div class="fts-ch">' + ctx.escapeHtml(h.vol ? h.vol + ' / ' : '') + ctx.escapeHtml(h.chTitle) + '</div>' +
                '<div class="fts-sn">' + hl + '</div>';
              item.addEventListener('click', () => {
                ctx.selectChapter(h.chId);
                ctx.toast('已跳转到：' + h.chTitle);
                const mask = item.closest('.drawer-mask');
                if (mask) mask.click();
              });
              list.appendChild(item);
            });
          };
          input.addEventListener('input', () => { clearTimeout(timer); timer = setTimeout(run, 200); });
          input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { clearTimeout(timer); run(); } });
          setTimeout(() => { try { input.focus(); } catch (e) {} }, 30);
        }
      });
    },
    deactivate() {}
  });
})();

/* 打字音效插件：写作时实时合成键盘声，6 种音色可选，带音量调节与试听。
 * 音效全部用 Web Audio 现场合成，不需要任何音频文件，也不联网。
 * 监听 #editor 的 keydown 事件；设置存 db.plugins（ctx.getSetting / ctx.setSetting）。
 */
(function () {
  'use strict';

  const PRESETS = {
    mech:       { name: '机械键盘',   desc: '清脆的咔哒声，带一点低频“thock”。' },
    typewriter: { name: '老式打字机', desc: '厚重的铛铛声，回车带一声清脆的铃。' },
    soft:       { name: '柔和',       desc: '安静绵软的滴答，适合深夜码字。' },
    wood:       { name: '木鱼',       desc: '清脆的木质敲击声。' },
    rain:       { name: '雨滴',       desc: '细密的雨声水滴，沙沙作响。' },
    retro:      { name: '复古游戏',   desc: '8-bit 方波音，敲起来像老游戏机。' }
  };

  function noiseBuffer(ac, dur) {
    const n = Math.max(1, Math.floor(ac.sampleRate * dur));
    const buf = ac.createBuffer(1, n, ac.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < n; i++) { const env = Math.pow(1 - i / n, 3); d[i] = (Math.random() * 2 - 1) * env; }
    return buf;
  }

  window.MoyePlugins.register({
    id: 'typewriter-sound',
    name: '打字音效',
    activate(ctx) {
      this._ctx = ctx;
      this.enabled = ctx.getSetting('tsEnabled', true);
      this.preset = ctx.getSetting('tsPreset', 'mech');
      this.volume = (ctx.getSetting('tsVolume', 60) || 60) / 100;
      this.audioCtx = null;
      this.master = null;
      this._onKey = (e) => this.onKey(e);
      this._ensure = () => this.ensureAudio();

      ctx.ui.addSettingsSection({
        title: '打字音效',
        render: (c) => this.renderSettings(c)
      });

      const ed = document.getElementById('editor');
      if (ed) ed.addEventListener('keydown', this._onKey);
      // 任意一次用户手势后解锁 AudioContext（浏览器/Electron 自动播放策略）
      document.addEventListener('keydown', this._ensure, { once: true });
      document.addEventListener('pointerdown', this._ensure, { once: true });
    },

    renderSettings(c) {
      const ctx = this._ctx;

      // 启用开关
      const enRow = document.createElement('label');
      enRow.className = 'set-check';
      enRow.innerHTML = '<input type="checkbox" id="tsEnabled"' + (this.enabled ? ' checked' : '') + '> 启用打字音效';
      c.appendChild(enRow);
      enRow.querySelector('#tsEnabled').addEventListener('change', (e) => {
        this.enabled = e.target.checked;
        ctx.setSetting('tsEnabled', this.enabled);
        if (this.enabled) this.ensureAudio();
      });

      // 音效预设（seg 分段按钮）
      const seg = document.createElement('div');
      seg.className = 'seg';
      seg.style.margin = '8px 0';
      Object.keys(PRESETS).forEach((k) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.dataset.v = k;
        b.textContent = PRESETS[k].name;
        if (k === this.preset) b.classList.add('active');
        b.addEventListener('click', () => {
          this.preset = k;
          ctx.setSetting('tsPreset', k);
          seg.querySelectorAll('button').forEach((x) => x.classList.toggle('active', x.dataset.v === k));
          hint.textContent = PRESETS[k].desc;
        });
        seg.appendChild(b);
      });
      c.appendChild(seg);
      const hint = document.createElement('div');
      hint.className = 'muted';
      hint.style.cssText = 'font-size:12px;margin:2px 0 8px;line-height:1.5';
      hint.textContent = PRESETS[this.preset].desc;
      c.appendChild(hint);

      // 音量
      const volRow = document.createElement('div');
      volRow.className = 'tool-row';
      volRow.style.marginTop = '4px';
      const volPct = Math.round(this.volume * 100);
      volRow.innerHTML =
        '<span class="muted" style="font-size:12px">音量</span>' +
        '<input type="range" id="tsVol" min="0" max="100" value="' + volPct + '" style="flex:1">' +
        '<b id="tsVolVal" style="font-size:12px;width:36px;text-align:right">' + volPct + '</b>';
      c.appendChild(volRow);
      const volInput = volRow.querySelector('#tsVol');
      const volVal = volRow.querySelector('#tsVolVal');
      volInput.addEventListener('input', () => {
        this.volume = (+volInput.value) / 100;
        volVal.textContent = volInput.value;
        if (this.master) this.master.gain.value = this.volume * 0.95;
        ctx.setSetting('tsVolume', +volInput.value);
      });

      // 试听
      const tryBtn = document.createElement('button');
      tryBtn.className = 'mini-btn primary';
      tryBtn.textContent = '试听一下';
      tryBtn.style.marginTop = '8px';
      tryBtn.addEventListener('click', () => {
        this.ensureAudio();
        this.play('KeyA', 'KeyA');
        setTimeout(() => this.play('Space', 'Space'), 90);
        setTimeout(() => this.play('Enter', 'Enter'), 180);
      });
      c.appendChild(tryBtn);
    },

    ensureAudio() {
      if (this.audioCtx) {
        if (this.audioCtx.state === 'suspended') { try { this.audioCtx.resume(); } catch (e) {} }
        return;
      }
      try {
        const AC = window.AudioContext || window.webkitAudioContext;
        this.audioCtx = new AC();
        this.master = this.audioCtx.createGain();
        this.master.gain.value = (this.volume || 0.6) * 0.95;
        this.master.connect(this.audioCtx.destination);
      } catch (e) { this.audioCtx = null; }
    },

    onKey(e) {
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      if (!this.enabled) return;
      this.ensureAudio();
      this.play(e.key, e.code);
    },

    play(key, code) {
      if (!this.audioCtx || !this.master) return;
      const isEnter = key === 'Enter';
      const isBack = key === 'Backspace';
      const isSpace = key === ' ';
      const isChar = (key && key.length === 1) || (code && /^Key|^Digit|^Numpad|^Period|^Comma/.test(code));
      if (!isEnter && !isBack && !isSpace && !isChar) return;
      const k = { isEnter, isBack, isSpace };
      const p = this.preset || 'mech';
      if (p === 'mech') this._mech(k);
      else if (p === 'typewriter') this._typewriter(k);
      else if (p === 'soft') this._soft(k);
      else if (p === 'wood') this._wood(k);
      else if (p === 'rain') this._rain(k);
      else if (p === 'retro') this._retro(k);
      else this._mech(k);
    },

    /* ───── 机械键盘：噪声脉冲 + 低频 thock ───── */
    _mech(k) {
      const ac = this.audioCtx, t = ac.currentTime;
      const src = ac.createBufferSource(); src.buffer = noiseBuffer(ac, 0.045);
      const bp = ac.createBiquadFilter(); bp.type = 'bandpass';
      bp.frequency.value = 1800 + Math.random() * 1000; bp.Q.value = 0.9;
      const g = ac.createGain(); g.gain.value = 0.85;
      src.connect(bp); bp.connect(g); g.connect(this.master);
      src.start(t); src.stop(t + 0.05);
      const o = ac.createOscillator(); o.type = 'triangle';
      o.frequency.value = (k.isEnter ? 150 : k.isSpace ? 120 : 165) + Math.random() * 30;
      const og = ac.createGain();
      og.gain.setValueAtTime(0.5, t);
      og.gain.exponentialRampToValueAtTime(0.001, t + 0.05);
      o.connect(og); og.connect(this.master);
      o.start(t); o.stop(t + 0.06);
      if (k.isEnter) this._bell(t);
    },

    /* ───── 老式打字机：更沉的咔哒 + 回车铃 ───── */
    _typewriter(k) {
      const ac = this.audioCtx, t = ac.currentTime;
      const src = ac.createBufferSource(); src.buffer = noiseBuffer(ac, 0.06);
      const bp = ac.createBiquadFilter(); bp.type = 'bandpass';
      bp.frequency.value = 700 + Math.random() * 400; bp.Q.value = 2;
      const g = ac.createGain(); g.gain.value = 0.95;
      src.connect(bp); bp.connect(g); g.connect(this.master);
      src.start(t); src.stop(t + 0.065);
      const o = ac.createOscillator(); o.type = 'square';
      o.frequency.value = (k.isEnter ? 200 : 180) + Math.random() * 25;
      const og = ac.createGain();
      og.gain.setValueAtTime(0.6, t);
      og.gain.exponentialRampToValueAtTime(0.001, t + 0.07);
      o.connect(og); og.connect(this.master);
      o.start(t); o.stop(t + 0.08);
      if (k.isEnter) this._bell(t);
    },

    _bell(t) {
      const ac = this.audioCtx;
      const o = ac.createOscillator(); o.type = 'sine'; o.frequency.value = 1180;
      const g = ac.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.5, t + 0.005);
      g.gain.exponentialRampToValueAtTime(0.0008, t + 0.35);
      o.connect(g); g.connect(this.master);
      o.start(t); o.stop(t + 0.4);
    },

    /* ───── 柔和：正弦滴答 ───── */
    _soft(k) {
      const ac = this.audioCtx, t = ac.currentTime;
      const o = ac.createOscillator(); o.type = 'sine';
      const base = k.isEnter ? 880 : k.isSpace ? 520 : 660 + Math.floor(Math.random() * 120);
      o.frequency.value = base;
      const g = ac.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.5, t + 0.004);
      g.gain.exponentialRampToValueAtTime(0.0008, t + 0.07);
      o.connect(g); g.connect(this.master);
      o.start(t); o.stop(t + 0.09);
    },

    /* ───── 木鱼：木质短促敲击 ───── */
    _wood(k) {
      const ac = this.audioCtx, t = ac.currentTime;
      const o = ac.createOscillator(); o.type = 'triangle';
      o.frequency.value = (k.isEnter ? 500 : k.isSpace ? 380 : 440) + Math.random() * 80;
      const g = ac.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.7, t + 0.003);
      g.gain.exponentialRampToValueAtTime(0.0008, t + 0.05);
      o.connect(g); g.connect(this.master);
      o.start(t); o.stop(t + 0.07);
    },

    /* ───── 雨滴：高频滤波噪声水滴 ───── */
    _rain(k) {
      const ac = this.audioCtx, t = ac.currentTime;
      const src = ac.createBufferSource(); src.buffer = noiseBuffer(ac, 0.05);
      const hp = ac.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 2400;
      const g = ac.createGain(); g.gain.value = 0.65;
      src.connect(hp); hp.connect(g); g.connect(this.master);
      src.start(t); src.stop(t + 0.05);
    },

    /* ───── 复古游戏：8-bit 方波 ───── */
    _retro(k) {
      const ac = this.audioCtx, t = ac.currentTime;
      const scale = [523, 587, 659, 784, 880];
      const o = ac.createOscillator(); o.type = 'square';
      o.frequency.value = k.isEnter ? 1046 : scale[Math.floor(Math.random() * scale.length)];
      const g = ac.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.4, t + 0.003);
      g.gain.exponentialRampToValueAtTime(0.0008, t + 0.06);
      o.connect(g); g.connect(this.master);
      o.start(t); o.stop(t + 0.08);
    },

    deactivate() {
      try { document.getElementById('editor').removeEventListener('keydown', this._onKey); } catch (e) {}
      try { document.removeEventListener('keydown', this._ensure); document.removeEventListener('pointerdown', this._ensure); } catch (e) {}
      try { if (this.audioCtx) this.audioCtx.close(); } catch (e) {}
      this.audioCtx = null; this.master = null;
    }
  });
})();
